import{_ as o,o as l,c as a,a4 as r}from"./chunks/framework.BBs01uty.js";const p=JSON.parse('{"title":"架构师思维练习 - 2026.08.14","description":"","frontmatter":{},"headers":[],"relativePath":"interview-questions/2026-08-14-architect.md","filePath":"interview-questions/2026-08-14-architect.md"}'),i={name:"interview-questions/2026-08-14-architect.md"};function s(e,t,n,u,g,q){return l(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="架构师思维练习-2026-08-14" tabindex="-1">架构师思维练习 - 2026.08.14 <a class="header-anchor" href="#架构师思维练习-2026-08-14" aria-label="Permalink to &quot;架构师思维练习 - 2026.08.14&quot;">​</a></h1><blockquote><p>练习&quot;做架构决策&quot;而不是背知识点。按难度分四层：L1 判断权衡 → L2 边界与契约 → L3 演进与综合 → L4 压力追问。 每题先<strong>独立作答</strong>（口头讲出来或写下来），再看参考答案要点自评。</p><p><strong>自评标准</strong>：你的回答里出现以下&quot;架构语言&quot;越多，得分越高—— 约束（什么条件下）、边界（谁管什么）、契约（接口固化）、权衡（代价是什么）、可逆性（错了能不能换）、机制（怎么落地而不是靠自觉）。</p></blockquote><hr><h2 id="l1-判断权衡-练-权衡账-每个选择都要说清代价" tabindex="-1">L1 判断权衡（练&quot;权衡账&quot;：每个选择都要说清代价） <a class="header-anchor" href="#l1-判断权衡-练-权衡账-每个选择都要说清代价" aria-label="Permalink to &quot;L1 判断权衡（练&quot;权衡账&quot;：每个选择都要说清代价）&quot;">​</a></h2><h3 id="_1-1-微前端-vs-巨石应用" tabindex="-1">1.1 微前端 vs 巨石应用 <a class="header-anchor" href="#_1-1-微前端-vs-巨石应用" aria-label="Permalink to &quot;1.1 微前端 vs 巨石应用&quot;">​</a></h3><p><strong>场景</strong>：公司要整合 5 条客服业务线（工作台、IM、知识库、质检、后台）为统一平台。业务线各自有独立团队、独立发布节奏，部分存量系统不能推翻重来。</p><p><strong>问题</strong>：你作为架构负责人，选&quot;巨石应用&quot;还是&quot;微前端&quot;？请说出你的决策和<strong>放弃的那个方案的代价</strong>。</p><p><strong>考察点</strong>：选型不是报答案，是把约束摆出来，再说明&quot;为什么这个约束下损失最小&quot;。</p><p>&lt;details&gt; &lt;summary&gt;参考答案要点&lt;/summary&gt;</p><ul><li>决策依据三句话：① 多团队并行 → 需要独立部署；② 存量系统 → 需要渐进改造；③ 业务线隔离 → 需要边界。</li><li>放弃巨石：代价是&quot;多团队一个仓库互相踩、发布互相阻塞、回归爆炸&quot;——在 5 条业务线规模下不可接受。</li><li>放弃 iframe：代价是&quot;体验割裂、通信弱、刷新丢状态&quot;——客服工作台高频操作场景体验是核心指标。</li><li>一句话收尾：<strong>微前端不是最优架构，是&quot;多团队独立交付&quot;这个约束下的损失最小解</strong>。 &lt;/details&gt;</li></ul><hr><h3 id="_1-2-自研组件库-vs-开源组件库" tabindex="-1">1.2 自研组件库 vs 开源组件库 <a class="header-anchor" href="#_1-2-自研组件库-vs-开源组件库" aria-label="Permalink to &quot;1.2 自研组件库 vs 开源组件库&quot;">​</a></h3><p><strong>场景</strong>：金融 SaaS 平台要做视觉规范统一，业务涉及表单、表格、文档模板等强业务组件。</p><p><strong>问题</strong>：基础组件层（Button、Input 之类）用 Antd，还是自研？业务组件层（信贷表单、模板渲染）呢？各自怎么选、理由是什么？</p><p><strong>考察点</strong>：组件库分层思维——基础层和业务层的决策依据完全不同。</p><p>&lt;details&gt; &lt;summary&gt;参考答案要点&lt;/summary&gt;</p><ul><li>基础层：用开源（Antd）。理由：生态、无障碍、维护成本——<strong>自研基础组件的代价（长期维护）远大于收益（定制感）</strong>，除非视觉规范与开源差异极大。</li><li>业务层：自研。理由：业务组件承载业务契约（数据模型、交互规则），开源没有；且跨项目复用价值高。</li><li>关键边界：<strong>自研业务组件依赖开源基础组件，反向禁止</strong>——基础层升级不影响业务层契约。 &lt;/details&gt;</li></ul><hr><h3 id="_1-3-状态管理选型" tabindex="-1">1.3 状态管理选型 <a class="header-anchor" href="#_1-3-状态管理选型" aria-label="Permalink to &quot;1.3 状态管理选型&quot;">​</a></h3><p><strong>场景</strong>：SaaS 表单系统，状态分三类：表单局部状态（用户正在填的内容）、跨页面全局状态（登录用户、权限）、服务端数据（贷款列表、模板列表，带缓存需求）。</p><p><strong>问题</strong>：三类状态分别用什么方案管理？选型依据是什么？</p><p><strong>考察点</strong>：不迷信某个库，按状态特征分类决策。</p><p>&lt;details&gt; &lt;summary&gt;参考答案要点&lt;/summary&gt;</p><ul><li>表单局部状态：组件内 state / 表单库内部管理——<strong>谁用谁管</strong>。</li><li>全局状态：轻量集中（Zustand/Redux 看团队），只放&quot;身份类&quot;信息。</li><li>服务端数据：请求层缓存（React Query/SWR）——<strong>服务端状态不该进全局 store</strong>，它是&quot;远端数据的本地缓存&quot;，有自己的生命周期（失效、重试、乐观更新）。</li><li>常见错误：把服务端数据全部塞进全局 store，缓存逻辑、失效策略全得手写。 &lt;/details&gt;</li></ul><hr><h2 id="l2-边界与契约-练-这个逻辑放哪-和-怎么固化边界" tabindex="-1">L2 边界与契约（练&quot;这个逻辑放哪&quot;和&quot;怎么固化边界&quot;） <a class="header-anchor" href="#l2-边界与契约-练-这个逻辑放哪-和-怎么固化边界" aria-label="Permalink to &quot;L2 边界与契约（练&quot;这个逻辑放哪&quot;和&quot;怎么固化边界&quot;）&quot;">​</a></h2><h3 id="_2-1-双层架构划边界" tabindex="-1">2.1 双层架构划边界 <a class="header-anchor" href="#_2-1-双层架构划边界" aria-label="Permalink to &quot;2.1 双层架构划边界&quot;">​</a></h3><p><strong>场景</strong>：一个信贷资料补充功能：后端返回表单 schema（字段、规则、值），前端要渲染表单、校验、提交；同套 schema 还用于&quot;编辑态&quot;和&quot;只读展示态&quot;。</p><p><strong>问题</strong>：数据构建层和 UI 展示层各自管什么？画一下职责清单。什么情况下这个边界是&quot;过度设计&quot;？</p><p><strong>考察点</strong>：边界判断 + 不过度设计的自知力。</p><p>&lt;details&gt; &lt;summary&gt;参考答案要点&lt;/summary&gt;</p><ul><li>数据层：schema 解析、默认值、校验逻辑（纯函数，无 DOM）、提交数据的组装。</li><li>展示层：表单控件渲染、布局、交互反馈。</li><li>边界收益：编辑态和展示态复用同一数据层 → 校验逻辑只写一份。</li><li>过度设计的判定：如果这个功能只有一种形态、schema 永远不会变，双层就是过度设计——<strong>边界跟着&quot;变化频率差异&quot;走，不跟着理论走</strong>。 &lt;/details&gt;</li></ul><hr><h3 id="_2-2-模板编辑器与生产渲染的契约" tabindex="-1">2.2 模板编辑器与生产渲染的契约 <a class="header-anchor" href="#_2-2-模板编辑器与生产渲染的契约" aria-label="Permalink to &quot;2.2 模板编辑器与生产渲染的契约&quot;">​</a></h3><p><strong>场景</strong>：模板编辑器产出文档模板，生产环境要按同一模板渲染出正式信件（邮件/PDF）。业务人员要求&quot;编辑器里预览的 = 最终发出去的&quot;。</p><p><strong>问题</strong>：怎么设计这条全链路，保证&quot;所见即所得&quot;？契约应该定义在哪？</p><p><strong>考察点</strong>：契约先于实现——把&quot;一致&quot;变成机制而不是承诺。</p><p>&lt;details&gt; &lt;summary&gt;参考答案要点&lt;/summary&gt;</p><ul><li>核心决策：<strong>编辑器和生产共用同一渲染内核</strong>——预览渲染和生产渲染是同一个函数，这是&quot;所见即所得&quot;唯一可靠的实现方式。</li><li>契约定义：模板数据结构（DocNode/schema）是双端契约，版本化演进；渲染内核是共享资产。</li><li>反面：编辑器用一套渲染、生产又写一套 → 再努力对齐也必然出现偏差，问题出在架构上不是实现上。 &lt;/details&gt;</li></ul><hr><h3 id="_2-3-多子应用统一权限" tabindex="-1">2.3 多子应用统一权限 <a class="header-anchor" href="#_2-3-多子应用统一权限" aria-label="Permalink to &quot;2.3 多子应用统一权限&quot;">​</a></h3><p><strong>场景</strong>：微前端平台，5+ 子应用，每个子应用有自己的页面权限需求。平台要求：登录一次，所有子应用可用（SSO），权限统一管理。</p><p><strong>问题</strong>：身份认证和授权分别放哪层？子应用要查&quot;用户有没有某按钮权限&quot;，怎么设计这个契约？</p><p><strong>考察点</strong>：身份（你是谁）和授权（你能干嘛）分离的边界思维。</p><p>&lt;details&gt; &lt;summary&gt;参考答案要点&lt;/summary&gt;</p><ul><li>身份认证：基座统一（登录、SSO、token 刷新），子应用不碰。</li><li>授权模型：基座提供&quot;权限数据 + 查询能力&quot;（当前用户、角色、权限点），<strong>判定逻辑</strong>（能不能点这个按钮）放子应用——基座管数据，业务管判定。</li><li>契约：子应用通过统一 API 查权限（而非自己存一份权限副本），权限变更靠刷新/推送生效。</li><li>常见错误：每个子应用各自维护登录和权限 → 改一次密码要登 5 次，权限加一个人要改 5 处。 &lt;/details&gt;</li></ul><hr><h2 id="l3-演进与综合-练-渐进式改造-和完整决策" tabindex="-1">L3 演进与综合（练&quot;渐进式改造&quot;和完整决策） <a class="header-anchor" href="#l3-演进与综合-练-渐进式改造-和完整决策" aria-label="Permalink to &quot;L3 演进与综合（练&quot;渐进式改造&quot;和完整决策）&quot;">​</a></h2><h3 id="_3-1-技术栈渐进迁移" tabindex="-1">3.1 技术栈渐进迁移 <a class="header-anchor" href="#_3-1-技术栈渐进迁移" aria-label="Permalink to &quot;3.1 技术栈渐进迁移&quot;">​</a></h3><p><strong>场景</strong>：存量系统 JS + Vue + 自研组件库，业务还要持续上新功能。你决定迁到 TS + React + 新组件库。</p><p><strong>问题</strong>：设计迁移路线：新老共存期间架构上怎么保证不烂？列出至少 3 个机制性的决策（不是&quot;大家注意点&quot;）。</p><p><strong>考察点</strong>：把不可逆的大改造拆成可逆小步骤的能力。</p><p>&lt;details&gt; &lt;summary&gt;参考答案要点&lt;/summary&gt;</p><ul><li>新模块新栈、老模块按需迁（不搞大爆炸），边界上靠路由层隔离。</li><li>公共能力（请求、权限、埋点）先抽成框架无关层，双栈共用——<strong>让两边都依赖&quot;中间件&quot;而不是互相依赖</strong>。</li><li>组件库分层：基础组件优先统一（双栈都能用），业务组件按模块灰度迁移。</li><li>类型先行：数据模型/接口类型先 TS 化（纯数据层可独立迁移，风险最低）。</li><li>收尾标准：老栈代码占比降到阈值（如 &lt;20%）再冻结；迁移期间埋点/监控双栈都接，灰度看指标。 &lt;/details&gt;</li></ul><hr><h3 id="_3-2-ai-工作流门禁设计" tabindex="-1">3.2 AI 工作流门禁设计 <a class="header-anchor" href="#_3-2-ai-工作流门禁设计" aria-label="Permalink to &quot;3.2 AI 工作流门禁设计&quot;">​</a></h3><p><strong>场景</strong>：团队用 AI 辅助开发，发现 Agent 经常&quot;跳步骤&quot;：不测试就宣布完成、方案没评审就动手、编造测试通过。</p><p><strong>问题</strong>：你是架构师，设计一套机制（不是提示词），让&quot;假完成&quot;无法通关。至少给出 3 层机制并说明各自的强度与成本。</p><p><strong>考察点</strong>：把&quot;不可靠的智能体&quot;用确定性机制约束——软约束到硬约束的递进思维。</p><p>&lt;details&gt; &lt;summary&gt;参考答案要点&lt;/summary&gt;</p><ul><li>L0 提示词约束（软）：流程要求写进系统提示词——成本为零，但 Agent 会绕过，强度最弱。</li><li>L1 结构化工作流（中）：YAML 定义阶段输入输出，产出物模板化（测试报告必须含&quot;声明用例数/实际运行数&quot;）——靠模板和阶段校验。</li><li>L2 工具 + Hook 门禁（硬）：验证命令必须通过工具执行，结果落盘为证据；阶段产出校验不达标则阻塞（exit 2 拦截）——<strong>证据链只能由工具产生，LLM 无法伪造</strong>。</li><li>关键认知：<strong>不能阻止 LLM 说谎，但可以让谎言无法通关</strong>——说谎的代价是阶段永远过不去。</li><li>强度与成本成正比：L2 最强但要做工具和 hook，按问题频率选择层数。 &lt;/details&gt;</li></ul><hr><h3 id="_3-3-微前端方案评审-逆向练习" tabindex="-1">3.3 微前端方案评审（逆向练习） <a class="header-anchor" href="#_3-3-微前端方案评审-逆向练习" aria-label="Permalink to &quot;3.3 微前端方案评审（逆向练习）&quot;">​</a></h3><p><strong>场景</strong>：新同事提交了一份微前端接入方案，你来做评审。方案要点：① 用 iframe 嵌入所有子应用；② 子应用间通信通过 window.postMessage 自由传递；③ 每个子应用独立打包 React（版本可能不同）；④ 基座通过定时器轮询 iframe 高度适配布局；⑤ 公共组件通过 npm 包发布，子应用各自安装任意版本。</p><p><strong>问题</strong>：找出至少 5 个问题，按严重程度排序，并说明各属什么架构维度（边界/契约/性能/体验/演进）。</p><p><strong>考察点</strong>：评审别人的架构——发现问题 + 排序优先级 + 归因维度。</p><p>&lt;details&gt; &lt;summary&gt;参考答案要点&lt;/summary&gt;</p><ol><li>iframe 嵌入（体验）：割裂感、刷新丢状态、键盘/焦点问题——客服工作台场景是体验核心，最严重。</li><li>postMessage 自由传递（契约缺失）：没有消息协议定义，变成&quot;蜘蛛网通信&quot;，无法审计——定义统一消息协议 + 白名单。</li><li>各自打包 React 版本不一（性能+包体积）：沙箱/多实例重复加载，内存翻倍——公共依赖 external + 版本锁定。</li><li>轮询高度适配（性能）：高频轮询损耗 + 抖动——用 ResizeObserver 等事件驱动。</li><li>组件库任意版本（演进）：版本碎片化，升级必然炸——semver + 升级策略（先灰度非核心）。</li><li>排序逻辑：先&quot;不可逆/伤体验&quot;的（1、3），再&quot;可治理&quot;的（2、5），最后&quot;性能细节&quot;（4）。 &lt;/details&gt;</li></ol><hr><h2 id="l4-压力追问-练-把决策讲成权衡账" tabindex="-1">L4 压力追问（练&quot;把决策讲成权衡账&quot;） <a class="header-anchor" href="#l4-压力追问-练-把决策讲成权衡账" aria-label="Permalink to &quot;L4 压力追问（练&quot;把决策讲成权衡账&quot;）&quot;">​</a></h2><h3 id="_4-1-连续追问模拟" tabindex="-1">4.1 连续追问模拟 <a class="header-anchor" href="#_4-1-连续追问模拟" aria-label="Permalink to &quot;4.1 连续追问模拟&quot;">​</a></h3><p><strong>场景</strong>：你刚讲完&quot;客服平台用了微前端&quot;，面试官开始连环追问：</p><ol><li>为什么不用 iframe？iframe 不是更简单吗？</li><li>你们 5 个子应用，其实巨石应用也能管吧？</li><li>微前端踩过最大的坑是什么？</li><li>现在回头看，如果重新选，你还选微前端吗？</li></ol><p><strong>问题</strong>：模拟作答，注意每道追问都要有&quot;承认代价 + 约束依据 + 当时信息&quot;的结构。</p><p><strong>考察点</strong>：不狡辩、不甩锅，承认代价但不推翻决策——这是架构师可信度的关键。</p><p>&lt;details&gt; &lt;summary&gt;参考答案要点&lt;/summary&gt;</p><ol><li>iframe：承认&quot;接入最简单&quot;，但代价是体验割裂（无过渡、刷新丢状态）和通信弱——工作台高频操作场景扛不住；Qiankun 在&quot;整合体验 vs 隔离&quot;更平衡。</li><li>巨石：如果只有 5 个人一个团队，巨石更划算，我承认；但约束是 5 条业务线独立团队独立发布，巨石意味着每次发布全员回归。</li><li>坑：公共依赖治理（React 多实例内存翻倍）、跨子应用联调环境、老代码绕沙箱——讲具体 + 讲对策。</li><li>重新选：还是会选微前端，但会<strong>更早把接入契约做成脚手架</strong>——早期人肉对齐的代价比预期大；顺便说&quot;如果约束变了（团队合并、发布统一），撤掉微前端也是合理决策&quot;——<strong>架构决策跟着约束走，不恋战</strong>。 &lt;/details&gt;</li></ol><hr><h2 id="练习方法建议" tabindex="-1">练习方法建议 <a class="header-anchor" href="#练习方法建议" aria-label="Permalink to &quot;练习方法建议&quot;">​</a></h2><ol><li><strong>每道题先口述</strong>（对着手机录音），再对照要点——口头表达会暴露逻辑缺口</li><li><strong>给每个回答标注&quot;架构语言&quot;命中数</strong>：约束/边界/契约/权衡/代价/可逆/机制，少于 3 个说明在报答案不是在讲决策</li><li>L1-L2 打基础，L3-3.3（评审题）最接近真实架构师日常，L4 用于面试前模拟</li><li>做完后可以对照 <a href="/knowledge/engineering/architect.html">什么是架构师</a> 文章的框架检查自己是否漏了维度</li></ol>',80)])])}const d=o(i,[["render",s]]);export{p as __pageData,d as default};
